/** 
 * Calls alter_table method using the metastore client. If the HMS supports it, environmental context will be set in a way that turns off stats updates to avoid recursive file listing.
 */
public static void alterTable(IMetaStoreClient client,String databaseName,String tblName,Table table,Map<String,String> extraEnv){
  Map<String,String> env=Maps.newHashMapWithExpectedSize(extraEnv.size() + 1);
  env.putAll(extraEnv);
  env.put(StatsSetupConst.DO_NOT_UPDATE_STATS,StatsSetupConst.TRUE);
  ALTER_TABLE.invoke(client,databaseName,tblName,table,new EnvironmentContext(env));
}
